export class File {
  private _account!: string;

  private _blob!: GenericId | null;

  private _chunks!: Chunk[] | null;

  private _container!: string | null;

  private _digest!: Digest | null;

  private _mime!: string;

  private _size!: bigint;

  private _tier!: number;

  private _virus!: string | null;

  constructor(arg?: FbsFile | Uint8Array) {
    if (arg instanceof Uint8Array) {
      const buf = new flatbuffers.ByteBuffer(arg);
      const fbs = FbsFile.getSizePrefixedRootAsFile(buf);
      this._initFromFbs(fbs);
    } else if (arg instanceof FbsFile) {
      this._initFromFbs(arg);
    } else {
      this._account = '';
      this._blob = null;
      this._chunks = null;
      this._container = null;
      this._digest = null;
      this._mime = '';
      this._size = BigInt(0);
      this._tier = 0;
      this._virus = null;
    }
  }

  private _initFromFbs(fbs: FbsFile): void {
    this._account = fbs.account() ?? '';
    const blobVal = fbs.blob();
    this._blob = blobVal ? new GenericId(blobVal) : null;
    if (fbs.chunksLength() > 0) {
      this._chunks = Array.from({ length: fbs.chunksLength() }, (_, i) => {
        const item = fbs.chunks(i);
        return item ? new Chunk(item) : new Chunk();
      });
    } else {
      this._chunks = null;
    }
    this._container = fbs.container();
    const digestTy = fbs.digestType();
    if (digestTy === FbsDigest.Sha256) {
      const digestFbsVal = fbs.digest(new FbsSha256());
      this._digest = digestFbsVal ? new Sha256(digestFbsVal) : null;
    } else {
      this._digest = null;
    }
    this._mime = fbs.mime() ?? '';
    this._size = fbs.size();
    this._tier = fbs.tier();
    this._virus = fbs.virus();
  }

  get account(): string {
    return this._account;
  }

  set account(value: string) {
    this._account = value;
  }

  get blob(): GenericId | null {
    return this._blob;
  }

  set blob(value: GenericId | null) {
    this._blob = value;
  }

  get chunks(): Chunk[] | null {
    return this._chunks;
  }

  set chunks(value: Chunk[] | null) {
    this._chunks = value;
  }

  get container(): string | null {
    return this._container;
  }

  set container(value: string | null) {
    this._container = value;
  }

  get digest(): Digest | null {
    return this._digest;
  }

  set digest(value: Digest | null) {
    this._digest = value;
  }

  get mime(): string {
    return this._mime;
  }

  set mime(value: string) {
    this._mime = value;
  }

  get size(): bigint {
    return this._size;
  }

  set size(value: bigint) {
    this._size = value;
  }

  get tier(): number {
    return this._tier;
  }

  set tier(value: number) {
    this._tier = value;
  }

  get virus(): string | null {
    return this._virus;
  }

  set virus(value: string | null) {
    this._virus = value;
  }

  toFbsT(): FbsFileT {
    const t = new FbsFileT();
    t.account = this._account;
    t.blob = this._blob ? this._blob.toFbsT() : null;
    t.chunks = this._chunks ? this._chunks.map(item => item.toFbsT()) : [];
    t.container = this._container;
    if (this._digest instanceof Sha256) {
      t.digestType = FbsDigest.Sha256;
      t.digest = this._digest.toFbsT();
    }
    t.mime = this._mime;
    t.size = this._size;
    t.tier = this._tier;
    t.virus = this._virus;
    return t;
  }

  toBytes(): Uint8Array {
    const builder = new flatbuffers.Builder();
    const offset = this.toFbsT().pack(builder);
    builder.finishSizePrefixed(offset);
    return builder.asUint8Array();
  }
}

