export class ListSlot {
  private _attributes!: Attr[] | null;

  private _entry!: ListEntry | null;

  private _id!: ObjectId;

  private _lastModifiedBy!: B2cId | null;

  private _name!: string;

  private _size!: bigint;

  private _time!: bigint;

  private _userPermissions!: number;

  constructor(arg?: FbsListSlot | Uint8Array) {
    if (arg instanceof Uint8Array) {
      const buf = new flatbuffers.ByteBuffer(arg);
      const fbs = FbsListSlot.getSizePrefixedRootAsListSlot(buf);
      this._initFromFbs(fbs);
    } else if (arg instanceof FbsListSlot) {
      this._initFromFbs(arg);
    } else {
      this._attributes = null;
      this._entry = null;
      this._id = new ObjectId();
      this._lastModifiedBy = null;
      this._name = '';
      this._size = BigInt(0);
      this._time = BigInt(0);
      this._userPermissions = 0;
    }
  }

  private _initFromFbs(fbs: FbsListSlot): void {
    if (fbs.attributesLength() > 0) {
      this._attributes = Array.from({ length: fbs.attributesLength() }, (_, i) => {
        const item = fbs.attributes(i);
        return item ? new Attr(item) : new Attr();
      });
    } else {
      this._attributes = null;
    }
    const entryTy = fbs.entryType();
    if (entryTy === FbsListEntry.ListFile) {
      const entryFbsVal = fbs.entry(new FbsListFile());
      this._entry = entryFbsVal ? new ListFile(entryFbsVal) : null;
    } else if (entryTy === FbsListEntry.ListDirectory) {
      const entryFbsVal = fbs.entry(new FbsListDirectory());
      this._entry = entryFbsVal ? new ListDirectory(entryFbsVal) : null;
    } else if (entryTy === FbsListEntry.ListObject) {
      const entryFbsVal = fbs.entry(new FbsListObject());
      this._entry = entryFbsVal ? new ListObject(entryFbsVal) : null;
    } else if (entryTy === FbsListEntry.TopLevelDirectory) {
      const entryFbsVal = fbs.entry(new FbsTopLevelDirectory());
      this._entry = entryFbsVal ? new TopLevelDirectory(entryFbsVal) : null;
    } else {
      this._entry = null;
    }
    const idVal = fbs.id();
    this._id = idVal ? new ObjectId(idVal) : new ObjectId();
    const lastModifiedByVal = fbs.lastModifiedBy();
    this._lastModifiedBy = lastModifiedByVal ? new B2cId(lastModifiedByVal) : null;
    this._name = fbs.name() ?? '';
    this._size = fbs.size();
    this._time = fbs.time();
    this._userPermissions = fbs.userPermissions();
  }

  get attributes(): Attr[] | null {
    return this._attributes;
  }

  set attributes(value: Attr[] | null) {
    this._attributes = value;
  }

  get entry(): ListEntry | null {
    return this._entry;
  }

  set entry(value: ListEntry | null) {
    this._entry = value;
  }

  get id(): ObjectId {
    return this._id;
  }

  set id(value: ObjectId) {
    this._id = value;
  }

  get lastModifiedBy(): B2cId | null {
    return this._lastModifiedBy;
  }

  set lastModifiedBy(value: B2cId | null) {
    this._lastModifiedBy = value;
  }

  get name(): string {
    return this._name;
  }

  set name(value: string) {
    this._name = value;
  }

  get size(): bigint {
    return this._size;
  }

  set size(value: bigint) {
    this._size = value;
  }

  get time(): bigint {
    return this._time;
  }

  set time(value: bigint) {
    this._time = value;
  }

  get userPermissions(): number {
    return this._userPermissions;
  }

  set userPermissions(value: number) {
    this._userPermissions = value;
  }

  toFbsT(): FbsListSlotT {
    const t = new FbsListSlotT();
    t.attributes = this._attributes ? this._attributes.map(item => item.toFbsT()) : [];
    if (this._entry instanceof ListFile) {
      t.entryType = FbsListEntry.ListFile;
      t.entry = this._entry.toFbsT();
    } else if (this._entry instanceof ListDirectory) {
      t.entryType = FbsListEntry.ListDirectory;
      t.entry = this._entry.toFbsT();
    } else if (this._entry instanceof ListObject) {
      t.entryType = FbsListEntry.ListObject;
      t.entry = this._entry.toFbsT();
    } else if (this._entry instanceof TopLevelDirectory) {
      t.entryType = FbsListEntry.TopLevelDirectory;
      t.entry = this._entry.toFbsT();
    }
    t.id = this._id.toFbsT();
    t.lastModifiedBy = this._lastModifiedBy ? this._lastModifiedBy.toFbsT() : null;
    t.name = this._name;
    t.size = this._size;
    t.time = this._time;
    t.userPermissions = this._userPermissions;
    return t;
  }

  toBytes(): Uint8Array {
    const builder = new flatbuffers.Builder();
    const offset = this.toFbsT().pack(builder);
    builder.finishSizePrefixed(offset);
    return builder.asUint8Array();
  }
}

